package nl.voetbalhub.app;
import android.app.Activity;
import android.webkit.*;
import android.widget.FrameLayout;
import java.net.HttpURLConnection;
import java.net.URL;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.ByteArrayOutputStream;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.json.JSONObject;
/** Bundled quiz. Only this native bridge owns the anonymous token; no remote script or arbitrary URL can use it. */
public final class ClubQuizView extends FrameLayout {
 private static final String BASE="https://voetbalhub-redactie.onrender.com/quiz/v1",PREFS="veldio_quiz39_private";
 private final WebView web;private boolean ready,disposed;private final Activity activity;private final ExecutorService network=new java.util.concurrent.ThreadPoolExecutor(2,2,0L,java.util.concurrent.TimeUnit.MILLISECONDS,new java.util.concurrent.ArrayBlockingQueue<Runnable>(4));private volatile String boardEtag="",boardKey="";
 public ClubQuizView(Activity a,Runnable back){super(a);activity=a;web=new WebView(a);web.setBackgroundColor(0xFF030806);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(true);web.getSettings().setAllowContentAccess(false);web.getSettings().setAllowFileAccessFromFileURLs(false);web.getSettings().setAllowUniversalAccessFromFileURLs(false);web.getSettings().setJavaScriptCanOpenWindowsAutomatically(false);web.getSettings().setSupportMultipleWindows(false);web.addJavascriptInterface(new Bridge(back),"ClubQuizHub");web.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String url){if("file:///android_asset/clubquiz.html".equals(url))ready=true;}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(!"file".equals(r.getUrl().getScheme()))return new WebResourceResponse("text/plain","UTF-8",new java.io.ByteArrayInputStream(new byte[0]));return null;}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){String url=r.getUrl().toString();if(r.isForMainFrame()&&r.hasGesture()&&url.startsWith("https://"))a.runOnUiThread(()->{if(disposed)return;new android.app.AlertDialog.Builder(a).setTitle("Externe feitenbron").setMessage("Je opent een website buiten Veldio. Die website heeft eigen privacyregels. Vraag bij twijfel een volwassene om mee te kijken.").setPositiveButton("Openen",(d,w)->{try{a.startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,r.getUrl()));}catch(Exception ignored){}}).setNegativeButton("Terug",null).show();});return true;}});addView(web,new LayoutParams(-1,-1));web.loadUrl("file:///android_asset/clubquiz.html");}
 private final class Bridge{
  private final Runnable back;Bridge(Runnable b){back=b;}
  @JavascriptInterface public void close(){activity.runOnUiThread(()->{if(!disposed)back.run();});}
  @JavascriptInterface public void share(String text){if(text==null||text.length()>2000)return;activity.runOnUiThread(()->{if(disposed)return;try{android.content.Intent intent=new android.content.Intent(android.content.Intent.ACTION_SEND);intent.setType("text/plain");intent.putExtra(android.content.Intent.EXTRA_TEXT,text);activity.startActivity(android.content.Intent.createChooser(intent,"Quizresultaat delen"));}catch(android.content.ActivityNotFoundException ignored){}});}
  @JavascriptInterface public void request(String id,String action,String raw){if(disposed||id==null||!id.matches("quiz[0-9]{1,12}")||action==null||raw==null||raw.length()>8192)return;try{long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(12);network.execute(()->perform(id,action,raw,deadline));}catch(java.util.concurrent.RejectedExecutionException e){try{deliver(id,503,new JSONObject().put("message","Quizverzoeken zijn nog bezig. Probeer opnieuw."));}catch(Exception ignored){}}}
 }
 private void deliver(String id,int status,JSONObject data){activity.runOnUiThread(()->{if(disposed||!ready)return;try{JSONObject packet=new JSONObject().put("status",status).put("data",data);web.evaluateJavascript("window.quizNativeReply("+JSONObject.quote(id)+","+JSONObject.quote(packet.toString())+")",null);}catch(Exception ignored){}});}
 private void perform(String id,String action,String raw,long deadline){HttpURLConnection c=null;DeadlineHttp.Guard guard=null;try{
  JSONObject data=new JSONObject(raw);String path,method="POST";switch(action){case "status":path="/status";method="GET";break;case "me":path="/me";method="GET";break;case "identity":path="/identity";break;case "checkName":path="/name/check";break;case "name":path="/name";break;case "alias":path="/alias";break;case "start":path="/round/start";break;case "answer":path="/round/answer";break;case "next":path="/round/next";break;case "report":path="/report";break;case "delete":path="/me";method="DELETE";break;case "round":path="/round?id="+java.net.URLEncoder.encode(data.optString("id"),"UTF-8");method="GET";break;case "board":String scope=data.optString("scope","live");if(!scope.matches("live|day|week|all"))throw new Exception("scope");path="/board?roundId="+java.net.URLEncoder.encode(data.optString("roundId"),"UTF-8")+"&scope="+scope;method="GET";break;default:deliver(id,400,new JSONObject().put("message","Onbekende quizactie."));return;}
  int remaining=(int)java.util.concurrent.TimeUnit.NANOSECONDS.toMillis(deadline-System.nanoTime());if(remaining<=0)throw new java.net.SocketTimeoutException("Total deadline");c=(HttpURLConnection)new URL(BASE+path).openConnection();guard=DeadlineHttp.watch(c,remaining);guard.check();c.setInstanceFollowRedirects(false);c.setConnectTimeout(Math.min(5000,remaining));c.setReadTimeout(Math.min(8000,remaining));c.setRequestMethod(method);c.setRequestProperty("Accept","application/json");c.setRequestProperty("Content-Type","application/json; charset=utf-8");String token=activity.getSharedPreferences(PREFS,0).getString("token","");if(!token.isEmpty()&&!"identity".equals(action)&&!"status".equals(action))c.setRequestProperty("Authorization","Bearer "+token);if("board".equals(action)&&path.equals(boardKey)&&!boardEtag.isEmpty())c.setRequestProperty("If-None-Match",boardEtag);
  if("POST".equals(method)){byte[] bytes=raw.getBytes(java.nio.charset.StandardCharsets.UTF_8);c.setDoOutput(true);c.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=c.getOutputStream()){out.write(bytes);}}
  int status=c.getResponseCode();guard.check();if(status==304){deliver(id,200,new JSONObject().put("notModified",true));return;}InputStream input=status>=400?c.getErrorStream():c.getInputStream();if(input==null)throw new Exception("empty");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=input){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){guard.check();out.write(b,0,n);if(out.size()>200000)throw new Exception("large");}}guard.check();JSONObject result=new JSONObject(out.toString("UTF-8"));if("identity".equals(action)&&status==201){String next=result.optString("token");if(!next.matches("[a-f0-9-]{36}\\.[A-Za-z0-9_-]{43}"))throw new Exception("identity");activity.getSharedPreferences(PREFS,0).edit().putString("token",next).apply();result.remove("token");}if("delete".equals(action)&&status==200){activity.getSharedPreferences(PREFS,0).edit().clear().apply();boardEtag="";}if("board".equals(action)&&status==200){boardKey=path;String tag=c.getHeaderField("ETag");boardEtag=tag==null?"":tag;}deliver(id,status,result);
 }catch(Exception e){try{deliver(id,503,new JSONObject().put("message","Geen verbinding met het quizklassement. Offline oefenen blijft mogelijk."));}catch(Exception ignored){}}finally{if(guard!=null)guard.close();else if(c!=null)c.disconnect();}}
 public boolean back(){if(!ready||disposed)return false;web.evaluateJavascript("if(!window.quizBack || !window.quizBack()) ClubQuizHub.close();",null);return true;}
 @Override protected void onWindowVisibilityChanged(int visibility){super.onWindowVisibilityChanged(visibility);if(web!=null&&ready&&!disposed)web.evaluateJavascript("window.quizForeground && window.quizForeground("+(visibility==VISIBLE?"true":"false")+")",null);}
 @Override protected void onDetachedFromWindow(){disposed=true;ready=false;network.shutdownNow();web.removeJavascriptInterface("ClubQuizHub");web.stopLoading();web.loadUrl("about:blank");removeAllViews();web.destroy();super.onDetachedFromWindow();}
}
